            group = str(h).strip()
            code = code.split(";")[0].strip()  # handle any trailing ';'
            if code and group and not code.lower().startswith("lookup"):
                lookup[code] = group

    # Fill column D (index 3) for rows 5..10.
    for r in range(5, 11):
