        if cell_c is None:
            continue
        codes = [c.strip() for c in str(cell_c).split(";")]
        codes = [c for c in codes if c]
        groups = []
        for code in codes:
            grp = lookup.get(code)
            if grp and grp not in groups:
                groups.append(grp)
        groups.sort(key=group_number)
        if not groups:
            result = ""
        elif len(groups) == 1:
            result = groups[0]
        else:
            result = ", ".join(groups)
        ws.cell(row=r, column=4).value = result

